function sha256(buffer) {
  return createHash("sha256").update(buffer).digest("hex");
}

async function currentHash(relativePath) {
  const absolutePath = resolve(root, relativePath);
  if (!existsSync(absolutePath)) return null;
  return sha256(await readFile(absolutePath));
}

async function readText(relativePath) {
  return readFile(resolve(root, relativePath), "utf8");
}

async function writeTextAtomic(relativePath, content) {
  const absolutePath = resolve(root, relativePath);
  await mkdir(dirname(absolutePath), { recursive: true });
  const tempPath = `${absolutePath}.entenarchiv-4619.tmp`;
  await writeFile(tempPath, content, "utf8");
  await rename(tempPath, absolutePath);
}

async function patchIndexVersion() {
  const file = "index.html";
  const source = await readText(file);
  if (source.includes('id="app-version">v4.6.19</span>')) return false;
  const pattern = /id="app-version">v4\.6\.18<\/span>/g;
  const matches = source.match(pattern) || [];
  if (matches.length !== 1) {
    throw new Error(`${file}: erwartete genau einen App-Versionsanker v4.6.18, gefunden wurden ${matches.length}.`);
  }
  await writeTextAtomic(file, source.replace(pattern, 'id="app-version">v4.6.19</span>'));
  return true;
}

async function patchChangelog() {
  const file = "CHANGELOG.md";
  if (!existsSync(resolve(root, file))) return false;
  let source = await readText(file);
  if (source.includes("## 4.6.19 – Architecture Runtime Hotfix")) return false;
  const section = `## 4.6.19 – Architecture Runtime Hotfix\n\n- \`createConditionBadge\` ist nach dem Feature-Split wieder als gemeinsames UI-Modul für App-Shell und Sammlung verdrahtet.\n- Zwei beim Calendar-Split verbliebene direkte Modal-Referenzen laufen jetzt über \`calendarFeature\`.\n- Regressionstests sichern diese Scope-Grenzen gegen Laufzeit-\`ReferenceError\`s ab.\n\n`;
  if (source.startsWith("# Änderungen")) {
    const firstBreak = source.indexOf("\n");
    source = `${source.slice(0, firstBreak + 1)}\n${section}${source.slice(firstBreak + 1).replace(/^\n+/, "")}`;
  } else {
    source = `# Änderungen\n\n${section}${source}`;
  }
  await writeTextAtomic(file, source);
  return true;
}

async function patchQualityReport() {
  const file = "QUALITY-REPORT.md";
  if (!existsSync(resolve(root, file))) return false;
  let source = await readText(file);
  let changed = false;
  if (/^# Qualitätsbericht Entenarchiv 4\.6\.18\s*$/m.test(source)) {
    source = source.replace(/^# Qualitätsbericht Entenarchiv 4\.6\.18\s*$/m, "# Qualitätsbericht Entenarchiv 4.6.19");
    changed = true;
  }
  if (!source.includes("## 4.6.19 Runtime-Hotfix")) {
    source = `${source.replace(/\s+$/, "")}\n\n## 4.6.19 Runtime-Hotfix\n\n- Gemeinsamer Zustands-Badge-Helfer für App-Shell und Sammlung wiederhergestellt.\n- Verbliebene Kalender-Modal-Scope-Referenzen auf die öffentliche Feature-API umgestellt.\n- Runtime-Scope-Regressionstests ergänzt.\n`;
    changed = true;
  }
  if (changed) await writeTextAtomic(file, source);
  return changed;
}

async function strictFilesAreFinal() {
  for (const file of files) {
    const actual = await currentHash(file.path);
    if (file.delete) {
      if (actual !== null) return false;
    } else if (actual !== file.finalHash) {
      return false;
    }
  }
  return true;
}

const packagePath = resolve(root, "package.json");
if (!existsSync(packagePath)) {
  throw new Error("package.json fehlt. Installer bitte im Root des ComicArchiv-Repositories ausführen.");
}
const packageJson = JSON.parse(await readFile(packagePath, "utf8"));

if (packageJson.version === TARGET_VERSION && await strictFilesAreFinal()) {
  await patchIndexVersion();
  await patchChangelog();
  await patchQualityReport();
  console.log(`✓ Entenarchiv ${TARGET_VERSION} ist bereits vollständig installiert.`);
  process.exit(0);
}

if (packageJson.version !== EXPECTED_FROM_VERSION) {
  throw new Error(`Sicherheitsstopp: erwartet wird Entenarchiv ${EXPECTED_FROM_VERSION}, gefunden wurde ${packageJson.version || "unbekannt"}. Es wurde nichts verändert.`);
}

// Runtime-/Build-/Testdateien bleiben weiterhin bytegenau abgesichert.
// CHANGELOG, QUALITY-REPORT und index.html werden absichtlich semantisch behandelt,
// damit harmlose Doku-/Markup-Abweichungen keinen Runtime-Hotfix blockieren.
const mismatches = [];
for (const file of files) {
  const actual = await currentHash(file.path);
  if (file.baselineHash === null) {
    if (actual !== null) mismatches.push(`${file.path}: sollte im ${EXPECTED_FROM_VERSION}-Ausgangsstand noch nicht existieren`);
  } else if (actual !== file.baselineHash) {
    mismatches.push(`${file.path}: Runtime-Ausgangsdatei weicht vom geprüften ${EXPECTED_FROM_VERSION}-Stand ab`);
  }
}
if (mismatches.length) {
  throw new Error(`Sicherheitsstopp vor der ersten Änderung:\n- ${mismatches.join("\n- ")}`);
}

// Auch index.html bekommt einen strukturellen Vorabcheck, bevor irgendeine Datei geschrieben wird.
const indexSource = await readText("index.html");
const indexAnchors = indexSource.match(/id="app-version">v4\.6\.18<\/span>/g) || [];
if (indexAnchors.length !== 1) {
  throw new Error(`Sicherheitsstopp vor der ersten Änderung: index.html besitzt nicht genau den erwarteten v4.6.18-Versionsanker.`);
}

for (const file of files) {
  if (file.delete) continue;
  const decoded = Buffer.from(file.data, "base64");
  if (sha256(decoded) !== file.finalHash) {
    throw new Error(`Interner Installer-Fehler: eingebetteter Hash für ${file.path} stimmt nicht.`);
  }
}

let changed = 0;
for (const file of files) {
  const absolutePath = resolve(root, file.path);
  if (file.delete) {
    await rm(absolutePath, { force: true });
    changed += 1;
    continue;
  }
  await mkdir(dirname(absolutePath), { recursive: true });
  const tempPath = `${absolutePath}.entenarchiv-4619.tmp`;
  const decoded = Buffer.from(file.data, "base64");
  await writeFile(tempPath, decoded);
  if (sha256(await readFile(tempPath)) !== file.finalHash) {
    await rm(tempPath, { force: true });
    throw new Error(`Schreibprüfung für ${file.path} fehlgeschlagen.`);
  }
  await rename(tempPath, absolutePath);
  changed += 1;
}

if (await patchIndexVersion()) changed += 1;
if (await patchChangelog()) changed += 1;
if (await patchQualityReport()) changed += 1;

const finalMismatches = [];
for (const file of files) {
  const actual = await currentHash(file.path);
  if (file.delete ? actual !== null : actual !== file.finalHash) finalMismatches.push(file.path);
}
if (finalMismatches.length) {
  throw new Error(`Abschlussprüfung fehlgeschlagen: ${finalMismatches.join(", ")}`);
}

const finalIndex = await readText("index.html");
if (!finalIndex.includes('id="app-version">v4.6.19</span>')) {
  throw new Error("Abschlussprüfung fehlgeschlagen: index.html zeigt nicht v4.6.19.");
}

console.log(`✓ Entenarchiv ${EXPECTED_FROM_VERSION} → ${TARGET_VERSION}: ${changed} Dateien sicher aktualisiert.`);
console.log("✓ Runtime-Dateien hart geprüft; Doku/Index semantisch und erhaltend aktualisiert.");
